  function wheelItem(settings,o,rng){const y=years(settings).max,rule=wheelRule(settings,o,rng),spokes=o.difficulty==='challenge'?8:6,inputs=Array.from({length:spokes},()=>randInt(rng,1,y<=2?10:15)),outputs=inputs.map(rule.apply),displayInputs=inputs.slice(),displayOutputs=outputs.slice(),indices=shuffle([...Array(spokes).keys()],rng);if(o.difficulty==='easy')indices.slice(0,2).forEach(i=>displayOutputs[i]=null);else if(o.difficulty==='standard'){indices.slice(0,3).forEach(i=>displayOutputs[i]=null);indices.slice(3,4).forEach(i=>displayInputs[i]=null);}else{indices.slice(0,4).forEach(i=>displayOutputs[i]=null);indices.slice(4,6).forEach(i=>displayInputs[i]=null);}return {style:'wheel',inputs,outputs,displayInputs,displayOutputs,rule:rule.label,ruleSpec:rule.spec};}
  function factorPairList(n){const pairs=[];for(let f=1;f<=Math.sqrt(n);f++)if(n%f===0)pairs.push([f,n/f]);return pairs;}
  function factorItem(settings,o,rng){const y=years(settings).max,pools=y<=2?[12,18,20,24,30]:y===3?[18,24,30,36,40,48,60]:[24,30,36,40,42,48,54,60,72,84,90,96,100,120],eligible=pools.filter(n=>factorPairList(n).length>=3),centre=choose(eligible,rng),pairs=factorPairList(centre).slice(0,6),mode=o.difficulty==='challenge'&&rng()<.4?'find_centre':'find_pairs',displayCentre=mode==='find_centre'?null:centre,displayPairs=pairs.map(()=>[null,null]);if(mode==='find_centre'){const shown=shuffle([...Array(pairs.length).keys()],rng).slice(0,Math.min(2,pairs.length));shown.forEach(i=>displayPairs[i]=pairs[i].slice());}else if(o.difficulty==='easy'&&pairs.length)displayPairs[0]=pairs[0].slice();return {style:'factor',centre,pairs,displayCentre,displayPairs,mode,instruction:mode==='find_centre'?'Use the shown factor pairs to find the centre number, then complete the web.':`Find the factor pairs of ${centre}.`};}
  function diamondItem(settings,o,rng){const y=years(settings).max,a=randInt(rng,1,y<=2?10:20),b=randInt(rng,1,y<=2?10:20),top=a*b,bottom=a+b;let hidden;if(o.difficulty==='easy')hidden=[rng()<.5?'top':'bottom'];else if(o.difficulty==='standard')hidden=choose([['top'],['bottom'],['left'],['right'],['top','left'],['bottom','right']],rng);else hidden=['left','right'];return {style:'diamond',left:a,right:b,top,bottom,hidden,orderIrrelevant:hidden.includes('left')&&hidden.includes('right')};}
  function generateNumberWheels(settings,seed){const rng=rngFromSeed(seed),o=normalise('numberwheels',settings?.engineSettings?.numberwheels),count=o.itemCount!=='auto'?Number(o.itemCount):(o.difficulty==='easy'?3:o.difficulty==='challenge'?6:4),style=o.style==='auto'?choose(o.difficulty==='easy'?['wheel','diamond']:['wheel','factor','diamond'],rng):o.style,items=Array.from({length:count},()=>style==='factor'?factorItem(settings,o,rng):style==='diamond'?diamondItem(settings,o,rng):wheelItem(settings,o,rng));if(style==='factor'&&o.difficulty!=='challenge'){const first=items.find(x=>x.mode==='find_pairs'&&x.pairs?.length);if(first&&!first.displayPairs.some(p=>p?.[0]!=null||p?.[1]!=null))first.displayPairs[0]=first.pairs[0].slice();}const title=style==='wheel'?'Rule Wheels':style==='factor'?'Factor Pair Webs':'Sum & Product Diamonds',instruction=style==='wheel'?'Use the centre rule to fill each blank input or output.':style==='factor'?(items.some(x=>x.mode==='find_centre')?'Each spoke is one factor pair: the two box numbers multiply to the centre number. Complete the missing boxes and any missing centre.':'Each spoke is one factor pair. Write one factor in each box so the two numbers multiply to the centre number.'):'The top is the product of the side numbers and the bottom is their sum. Fill the blanks.'+(items.some(x=>x.orderIrrelevant)?' When both side numbers are blank, they may be written either way round.':'');return {engineId:'numberwheels',title,difficulty:o.difficulty,style,items,instruction,seed,options:o};}

  function machineOpPool(settings,diff){const y=years(settings).max;const ops=['+','-'];if(y>=2)ops.push('×');if(y>=3&&diff==='challenge')ops.push('÷');return ops;}
  function applyMachine(v,op){return evalOp(v,op.op,op.value);}
  function generateFunctionMachine(settings,seed){const rng=rngFromSeed(seed),o=normalise('functionmachine',settings?.engineSettings?.functionmachine),stages=o.stages!=='auto'?Number(o.stages):(o.difficulty==='easy'?1:o.difficulty==='challenge'?3:2),ops=[];for(let i=0;i<stages;i++){let symbol=choose(machineOpPool(settings,o.difficulty),rng);if(symbol==='÷'&&ops.some(x=>x.op==='÷'))symbol=choose(machineOpPool(settings,o.difficulty).filter(x=>x!=='÷'),rng);let value=symbol==='×'||symbol==='÷'?randInt(rng,2,years(settings).max<=2?5:6):randInt(rng,1,years(settings).max<=2?10:15);for(let guard=0;guard<20&&ops.some(x=>x.op===symbol&&x.value===value);guard++){symbol=choose(machineOpPool(settings,o.difficulty),rng);value=symbol==='×'||symbol==='÷'?randInt(rng,2,years(settings).max<=2?5:6):randInt(rng,1,years(settings).max<=2?10:15);}ops.push({op:symbol,value});}
    const rowCount=clamp(Number(o.rowCount)||5,4,6),candidates=[],inputCap=o.difficulty==='challenge'?200:100,outputCap=o.difficulty==='challenge'?2000:1000;for(let input=1;input<=inputCap&&candidates.length<80;input++){let output=input,valid=true;for(const op of ops){if(op.op==='÷'&&output%op.value!==0){valid=false;break;}output=applyMachine(output,op);if(!Number.isInteger(output)||output<0||output>outputCap){valid=false;break;}}if(valid)candidates.push({input,output});}
    if(candidates.length<rowCount)return generateFunctionMachine(settings,`${seed}:retry`);
    const chosen=shuffle(candidates,rng).slice(0,rowCount).sort((a,b)=>a.input-b.input),rows=chosen.map(({input,output})=>({input,output,hide:o.direction==='forward'?'output':o.direction==='reverse'?'input':(rng()<.5?'output':'input')}));
    return {engineId:'functionmachine',title:'Function Machines',difficulty:o.difficulty,operations:ops,rows,instruction:'Use the machine rule from left to right. Where the input is missing, work backwards using inverse operations.',seed,options:o};}

  function makeBalanceRow(settings,o,rng){const y=years(settings).max,style=o.style==='auto'?(o.difficulty==='challenge'&&rng()<.45?'expression':'number'):o.style;if(style==='expression'){const a=randInt(rng,2,y<=2?20:60),b=randInt(rng,1,y<=2?10:30),total=a+b,c=randInt(rng,1,Math.max(1,total-1)),missing=total-c;return {display:`${a} + ${b} = ${c} + □`,answer:missing,solution:`${a} + ${b} = ${c} + ${missing}`};}
    if(o.difficulty==='challenge'&&y>=4){const x=randInt(rng,2,15),k=randInt(rng,2,5),rhs=k*x;return {display:`${k} × □ = ${rhs}`,answer:x,solution:`${k} × ${x} = ${rhs}`};}
    const a=randInt(rng,2,y<=2?20:100),b=randInt(rng,1,Math.min(a,y<=2?10:50)),total=a+b,c=randInt(rng,1,total),missing=total-c;return {display:`${a} + ${b} = ${c} + □`,answer:missing,solution:`${a} + ${b} = ${c} + ${missing}`};}
  function generateBalance(settings,seed){const rng=rngFromSeed(seed),o=normalise('balance',settings?.engineSettings?.balance),n=o.rowCount!=='auto'?Number(o.rowCount):(o.difficulty==='easy'?5:o.difficulty==='challenge'?8:6),rows=Array.from({length:n},()=>makeBalanceRow(settings,o,rng));return {engineId:'balance',title:'Balance the Equation',difficulty:o.difficulty,rows,instruction:'Find the missing value so both sides of every equals sign have the same value.',seed,options:o};}

  function generate(id,settings,seed){if(id==='arithmagon')return generateArithmagon(settings,seed);if(id==='magicshape')return generateMagicShape(settings,seed);if(id==='maze')return generateMaze(settings,seed);if(id==='crossnumber')return generateCrossnumber(settings,seed);if(id==='numbersearch')return generateNumberSearch(settings,seed);if(id==='equationcrossgrid')return generateEquationCrossgrid(settings,seed);if(id==='numbertrail')return generateNumberTrail(settings,seed);if(id==='target')return generateTarget(settings,seed);if(id==='brokencalc')return generateBrokenCalc(settings,seed);if(id==='symbols')return generateSymbols(settings,seed);if(id==='domino')return generateDomino(settings,seed);if(id==='operationgrid')return generateOperationGrid(settings,seed);if(id==='numberwheels')return generateNumberWheels(settings,seed);if(id==='functionmachine')return generateFunctionMachine(settings,seed);if(id==='balance')return generateBalance(settings,seed);return null;}

  function workedExample(id,settings,seed){const base={engineId:id,title:`${DEFINITIONS[id]?.title||id} worked example`,kind:id};if(id==='arithmagon')return {...base,goal:'Use the rule on each side to find a missing value.',rules:['Each side value comes from the two corner values it joins.','For an addition arithmagon, add corners going forwards and subtract to work backwards.'],steps:['Corners 4 and 7 give side 11 because 4 + 7 = 11.','If a side is 11 and one corner is 4, the other corner is 11 − 4 = 7.','Check the same corner against its other side.'],tip:'A missing corner usually belongs to two sides, so you can check it twice.',commonMistake:'Do not combine corners that are not joined by a side.'};
    if(id==='magicshape')return {...base,goal:'Make every marked line have the same total.',rules:['Add all numbers on one complete line to find the magic total.','Every other marked line must match it.'],steps:['A complete line totals 18, so 18 is the target.','Another line shows 5 + □ + 6 = 18.','5 + 6 = 11, so the missing number is 18 − 11 = 7.'],tip:'Start with a line that has only one blank.',commonMistake:'Only add numbers that lie on the same marked line.'};
    if(id==='maze')return {...base,goal:'Solve each question and move through the answer grid from START to FINISH.',rules:['Solve question 1 first.','From your current square, move only up, down, left or right to the neighbouring square containing that answer.','Continue with the next numbered question until you reach FINISH.'],steps:['Start on START and read question 1: 7 × 6.','7 × 6 = 42.','Look only at the squares touching START above, below, left or right; move to 42.','Now solve question 2 from your new square and repeat until FINISH.'],tip:'Cross out or lightly mark each answer square as you use it so you can see your route.',commonMistake:'Do not move diagonally, and do not jump to the right answer elsewhere in the grid — it must be a neighbouring square.'};
    if(id==='crossnumber')return {...base,goal:'Solve a numerical clue and write its digits into the grid.',rules:['Across answers go left to right; Down answers go top to bottom.','Each box contains one digit.','Crossing answers must share the same digit.'],steps:['Clue: 8 × 7.','8 × 7 = 56.','Write 5 then 6 into the two answer cells.','Use any crossing digit to help with another clue.'],tip:'Solve the easiest clues first to gain crossing digits.',commonMistake:'Do not write operation signs or units into the grid — only the numerical answer.'};
    if(id==='numbersearch')return {...base,goal:'Calculate each numerical answer and find its digits hidden in the grid.',rules:['Solve the calculation before searching.','Digits in one answer stay in one straight line.','Depending on difficulty, answers may be horizontal, vertical, diagonal or backwards.'],steps:['Question: 18 × 7.','18 × 7 = 126.','Look for the consecutive digits 1, 2, 6 in one allowed direction.','Circle or shade the complete answer string.'],tip:'Longer answers are usually easier to spot, so try those first.',commonMistake:'Do not change direction halfway through a number.'};
    if(id==='equationcrossgrid')return {...base,goal:'Complete linked across and down equations.',rules:['Every white row or column segment forms a true equation.','A number cell can belong to both an across and a down equation.','Missing operation signs must also make the whole equation true.'],steps:['Read one line with only one blank.','Use the visible numbers and sign to solve that blank.','Write the value in the shared cell.','Use the new value to unlock a crossing equation.'],tip:'Start where an equation has just one missing part.',commonMistake:'Check both directions when a number sits at an intersection.'};
    if(id==='numbertrail')return {...base,goal:'Continue a number pattern along the path.',rules:['Move through the cells in path order.','Apply the same rule at every step unless the puzzle says the rule alternates.'],steps:['Rule: +4 each step.','12 + 4 = 16.','16 + 4 = 20.','20 + 4 = 24, so the next blank is 24.'],tip:'Check several neighbouring values before deciding a missing number.',commonMistake:'Do not restart the rule after a blank; the pattern continues through it.'};
    if(id==='target')return {...base,goal:'Combine the supplied numbers to make the target.',rules:['Use only the allowed operations.','Use each supplied number at most once unless the puzzle says otherwise.'],steps:['Numbers: 2, 3, 4. Target: 10.','Multiply 2 × 3 = 6.','Then 6 + 4 = 10.','One solution is (2 × 3) + 4 = 10.'],tip:'Try multiplication first when the target is much larger than the starting numbers.',commonMistake:'Do not use a number twice unless two copies were supplied.'};
    if(id==='brokencalc')return {...base,goal:'Reach the target using only the calculator keys that still work.',rules:['Every digit and operation in your solution must be on the working-key list.','You may press a working key more than once.','Normal order of operations applies: multiplication and division before addition and subtraction.'],steps:['Working keys: 2, 5, 7, +, ×, =. Target: 17.','Enter 7 + 2 × 5.','Work out 2 × 5 = 10 first, then 7 + 10 = 17.','The target is reached without using any broken key.'],tip:'Build a useful multiplication or division first when it helps you approach the target.',commonMistake:'Do not calculate a mixed expression strictly from left to right; use normal order of operations.'};
    if(id==='symbols')return {...base,goal:'Use linked equations to find the value of each unknown.',rules:['The same letter always represents the same number.','Use an equation with only one unknown value first.'],steps:['A + A = 10, so A = 5.','A + B = 12.','Substitute A = 5: 5 + B = 12.','Therefore B = 7.'],tip:'Write each discovered value beside the letter before moving on.',commonMistake:'Do not change the value of a symbol from one equation to another.'};
    if(id==='domino')return {...base,goal:'Arrange calculation dominoes into one continuous chain.',rules:['Solve the calculation on the right half.','Its answer matches the left half of the next domino.'],steps:['START | 6 × 4 gives 24.','Find the domino whose left side is 24.','Solve that domino and continue.','Stop when you reach END.'],tip:'Pencil the answer above each calculation first.',commonMistake:'Match the answer, not a number that merely looks similar.'};
    if(id==='operationgrid')return {...base,goal:'Choose the missing operation sign that makes an equation true.',rules:['Try the permitted operations.','Check the complete equation after filling the box.'],steps:['8 □ 4 = 12.','8 + 4 = 12, so + works.','8 − 4 = 4, so − does not work.','Write + in the box.'],tip:'Estimate whether the answer should get bigger or smaller before trying a sign.',commonMistake:'For two-operation questions, follow the brackets shown.'};
    if(id==='numberwheels')return {...base,title:'Number Connections worked example',goal:'Read the diagram style, then use its number relationship to fill the missing values.',rules:['Rule Wheel: apply the centre operation between each inner and outer value.','Factor Pair Web: the two numbers on each spoke multiply to the centre number.','Sum & Product Diamond: the side numbers multiply to make the top and add to make the bottom.'],steps:['Rule Wheel example: ×6 turns inner 4 into outer 24; if outer 30 is given, work backwards with 30 ÷ 6 = 5.','Factor Pair Web example: for centre 12, valid pairs include 1×12, 2×6 and 3×4.','Diamond example: side numbers 3 and 4 give product 12 at the top and sum 7 at the bottom.'],tip:'Identify whether you have a wheel, factor web or diamond before calculating.',commonMistake:'Do not apply the Rule Wheel operation to a Factor Pair Web or Sum & Product Diamond; each diagram style has its own relationship.'};
    if(id==='functionmachine')return {...base,goal:'Follow operations through the machine or reverse them to find an input.',rules:['Apply stages from left to right.','To work backwards, use inverse operations in reverse order.'],steps:['Machine: ×3, then +2. Input 4.','4 × 3 = 12.','12 + 2 = 14, so the output is 14.','To reverse from 14: 14 − 2 = 12, then 12 ÷ 3 = 4.'],tip:'Write the intermediate value between stages.',commonMistake:'When reversing, undo the last operation first.'};
    if(id==='balance')return {...base,goal:'Keep both sides of the equals sign equal.',rules:['Calculate the known side first.','Find the missing amount needed to make the other side the same.'],steps:['7 + 8 = 10 + □.','7 + 8 = 15.','10 + □ must also equal 15.','15 − 10 = 5, so □ = 5.'],tip:'Treat = as “has the same value as”, not “the answer comes next”.',commonMistake:'Do not change a number on the other side to make your answer fit.'};return null;}

  function validate(a){if(!a||a.error)return {ok:false,error:a?.error||'missing activity'};if(a.engineId==='arithmagon'){for(const link of a.links||[]){const op=link.operation==='add'?'+':'×';if(evalOp(a.corners[link.a],op,a.corners[link.b])!==link.value)return {ok:false,error:'arithmagon link mismatch'};}}
    if(a.engineId==='magicshape'){for(const line of a.lines){const sum=line.reduce((s,i)=>s+a.solutionValues[i],0);if(sum!==a.target)return {ok:false,error:'magic shape line mismatch'};}}
    if(a.engineId==='maze'){if(!Array.isArray(a.path)||a.path.length!==a.steps.length+2)return {ok:false,error:'maze path length mismatch'};const seen=new Set();for(let i=0;i<a.path.length;i++){const [x,y]=a.path[i],key=`${x}:${y}`;if(seen.has(key))return {ok:false,error:'maze path repeats a cell'};seen.add(key);if(i){const [px,py]=a.path[i-1];if(Math.abs(x-px)+Math.abs(y-py)!==1)return {ok:false,error:'maze path not orthogonally connected'};}const cell=a.grid?.[y]?.[x];if(!cell)return {ok:false,error:'maze route points to missing cell'};if(i===0&&cell.kind!=='start')return {ok:false,error:'maze missing START'};if(i===a.path.length-1&&cell.kind!=='finish')return {ok:false,error:'maze missing FINISH'};if(i>0&&i<a.path.length-1&&(cell.kind!=='answer'||String(cell.value)!==String(a.steps[i-1].answer)))return {ok:false,error:'maze answer path mismatch'};}}
    if(a.engineId==='crossnumber'){
      const occupancy=crossnumberOccupancy(a.entries||[]);
      for(const e of a.entries||[]){
        let hasPrivateCell=false;
        for(let i=0;i<e.cells.length;i++){
          const [x,y]=e.cells[i],members=occupancy.get(`${x}:${y}`)||[];
          if(a.grid[y][x]!==String(e.answer)[i])return {ok:false,error:'crossnumber grid mismatch'};
          if(members.filter(v=>v.dir===e.dir).length>1)return {ok:false,error:'crossnumber parallel overlap'};
          if(members.length===1)hasPrivateCell=true;
        }
        if(!hasPrivateCell)return {ok:false,error:'crossnumber redundant clue'};
      }
    }
    if(a.engineId==='numbersearch'){for(const e of a.placements||[]){for(let i=0;i<e.cells.length;i++){const [x,y]=e.cells[i];if(a.grid[y][x]!==String(e.answer)[i])return {ok:false,error:'number search placement mismatch'};}if((a.accidentalMatches||0)===0){const matches=numberSearchOccurrences(a.grid,String(e.answer),a.mode);if(matches.length!==1||!sameSearchCells(matches[0].cells,e.cells))return {ok:false,error:'number search answer is ambiguous'};}}}
    if(a.engineId==='equationcrossgrid'){const g=a.solutionGrid||[],lines=a.lines||[];if(!lines.length)return {ok:false,error:'crossgrid missing equation lines'};for(const line of lines){if(!Array.isArray(line.cells)||line.cells.length!==5)return {ok:false,error:'crossgrid malformed line'};const [ap,op,bp,eqp,rp]=line.cells,a0=Number(g?.[ap[0]]?.[ap[1]]),op0=g?.[op[0]]?.[op[1]],b0=Number(g?.[bp[0]]?.[bp[1]]),eq0=g?.[eqp[0]]?.[eqp[1]],res=Number(g?.[rp[0]]?.[rp[1]]);if(eq0!=='='||!['+','-','×','÷'].includes(op0)||!Number.isFinite(a0)||!Number.isFinite(b0)||!Number.isFinite(res)||Math.abs(crossgridApply(a0,op0,b0)-res)>1e-9)return {ok:false,error:'crossgrid equation mismatch'};}if(!crossgridResolvableLines(lines,a.hiddenKeys||[]))return {ok:false,error:'crossgrid hidden set not sequentially solvable'};}
    if(a.engineId==='numbertrail'){for(let i=1;i<a.values.length;i++){const prev=a.values[i-1],expected=a.rule.multiplier?prev*a.rule.multiplier:prev+a.rule.steps[(i-1)%a.rule.steps.length];if(a.values[i]!==expected)return {ok:false,error:'trail rule mismatch'};}}
    if(a.engineId==='target'){for(const c of a.challenges)if(!Number.isFinite(c.target))return {ok:false,error:'target invalid'};}
    if(a.engineId==='symbols'){for(let i=0;i<a.values.length;i++)if(!Number.isFinite(a.values[i]))return {ok:false,error:'symbol invalid'};}
    if(a.engineId==='domino'){if(a.ordered[0].left!=='START'||a.ordered.at(-1).right!=='END')return {ok:false,error:'domino endpoints'};for(let i=0;i<a.ordered.length-1;i++){if(a.ordered[i].right==='END')break;if(String(a.ordered[i].rightAnswer)!==String(a.ordered[i+1].left))return {ok:false,error:'domino chain mismatch'};}}
    if(a.engineId==='operationgrid'){for(const r of a.rows){let v=Number(r.a);if(r.c!==undefined){v=evalOp(v,r.ops[0],Number(r.b));v=evalOp(v,r.ops[1],Number(r.c));}else v=evalOp(v,r.ops[0],Number(r.b));if(Math.abs(v-r.result)>1e-9)return {ok:false,error:'operation row mismatch'};}}
    if(a.engineId==='numberwheels'){for(const item of a.items||[]){if(item.style==='wheel'){const spec=item.ruleSpec||{};for(let i=0;i<item.inputs.length;i++){const input=item.inputs[i],expected=spec.type==='add'?input+spec.a:spec.type==='multiply'?input*spec.a:spec.type==='multiply_add'?input*spec.a+spec.b:NaN;if(expected!==item.outputs[i])return {ok:false,error:'rule wheel mismatch'};}}else if(item.style==='factor'){for(const [u,v] of item.pairs||[])if(u*v!==item.centre)return {ok:false,error:'factor web mismatch'};}else if(item.style==='diamond'){if(item.left*item.right!==item.top||item.left+item.right!==item.bottom)return {ok:false,error:'diamond mismatch'};}}}
    if(a.engineId==='functionmachine'){for(const r of a.rows){let v=r.input;for(const op of a.operations)v=applyMachine(v,op);if(v!==r.output)return {ok:false,error:'machine mismatch'};}}
    if(a.engineId==='balance'){for(const r of a.rows)if(!Number.isFinite(Number(r.answer)))return {ok:false,error:'balance answer invalid'};}
    return {ok:true};}

  const api={VERSION,NUMERIC_TOPICS,PRIMARY_ARITH,DEFINITIONS,normalise,generate,workedExample,validate,makeNumericItem,rngFromSeed,fmt,_evalOp:evalOp,_matrixRank:matrixRank,_STAR_LINES:STAR_LINES,_STAR_BASE:STAR_BASE,_BOWTIE_LINES:BOWTIE_LINES,_operationSolutions:operationSolutions,_eligibleTopics:eligibleTopics};
  if(typeof module!=='undefined'&&module.exports)module.exports=api;global.TT99ArithmeticGames=api;
